def apply_discounts(total, codes, table):
    t = float(total)
    rejected = []
    for code in codes:
        try:
            v = table[code]
        except KeyError:
            rejected.append(code)
            continue
        if 0 < v < 1:
            t -= t * v
        else:
            t -= v
    return {'total': t, 'rejected': rejected}

